@prefix rim: <https://w3id.org/ogc/rim/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/rim/i-ungoverned> ;
            sh:resultMessage "Value does not have class rim:RegisterItemClass" ;
            sh:resultPath rim:itemClass ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:ClassConstraintComponent ;
            sh:sourceShape [ sh:class rim:RegisterItemClass ;
                    sh:maxCount 1 ;
                    sh:minCount 1 ;
                    sh:path rim:itemClass ] ;
            sh:value <https://example.org/rim/uc> ] .

